// Run Once for All Items
const item = $input.first();
let out = item?.json?.output;
if (typeof out === "string") {
  try { out = JSON.parse(out); } catch { out = {}; }
}
const texto = ((out && out.respuesta) || "").toString().trim();
if (!texto) return [{ json: { mensaje: "" } }];

let bloques = texto.split(/\n{2,}/).map(s => s.trim()).filter(Boolean);
if (bloques.length === 1) {
  bloques = texto.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(Boolean);
}

let mensajes;
if (bloques.length <= 4) {
  mensajes = bloques;
} else {
  const grupos = [[], [], [], []];
  const porGrupo = Math.max(1, Math.ceil(bloques.length / 4));
  bloques.forEach((b, i) => {
    const idx = Math.min(Math.floor(i / porGrupo), 3);
    grupos[idx].push(b);
  });
  mensajes = grupos.map(g => g.join(" ")).filter(Boolean);
}

return mensajes.map(m => ({ json: { mensaje: m } }));

